<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$userId=(int)current_user()['user_id'];$st=$pdo->prepare('SELECT * FROM users WHERE user_id=?');$st->execute([$userId]);$profile=$st->fetch();$st=$pdo->prepare('SELECT us.*,s.skill_name,sc.category_name FROM user_skills us JOIN skills s ON s.skill_id=us.skill_id LEFT JOIN skill_categories sc ON sc.category_id=s.category_id WHERE us.user_id=? ORDER BY us.verified_level DESC,us.self_assessed_level DESC,s.skill_name');$st->execute([$userId]);$skills=$st->fetchAll();$st=$pdo->prepare("SELECT e.title,e.evidence_url,e.status,e.submitted_at,s.skill_name,p.title project_title FROM evidence_submissions e JOIN skills s ON s.skill_id=e.skill_id LEFT JOIN projects p ON p.project_id=e.project_id WHERE e.user_id=? AND e.status='verified' ORDER BY e.submitted_at DESC");$st->execute([$userId]);$verified=$st->fetchAll();$st=$pdo->prepare('SELECT ua.awarded_at,a.title,a.description,a.icon_name FROM user_achievements ua JOIN achievements a ON a.achievement_id=ua.achievement_id WHERE ua.user_id=? ORDER BY ua.awarded_at DESC');$st->execute([$userId]);$achievements=$st->fetchAll();$pageTitle='My Skill Passport';$active='passport';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Your demonstrated growth</span><h1 class="h1">My Skill Passport</h1><p>A personal summary of the skills you have assessed and the evidence reviewers have approved.</p></div><button class="btn btn-outline" onclick="window.print()">Print / Save PDF ↗</button></div><section class="passport-banner"><div class="passport-profile"><span class="avatar"><?=h(initials($profile['full_name']))?></span><div><h1><?=h($profile['full_name'])?></h1><p><?=h($profile['department']?:'Student')?><?= $profile['college_name']?' · '.h($profile['college_name']):''?><?= $profile['graduation_year']?' · Class of '.h($profile['graduation_year']):''?></p><p><?=h($profile['email'])?></p></div></div><p style="color:#c6d7ed;font-size:12px;margin:20px 0 0">This passport is a user-owned progress summary. Verified status reflects reviews recorded within this platform and is not an external certification.</p></section><div class="grid grid-2" style="margin-top:20px;align-items:start"><section class="card card-pad"><div class="panel-title"><h3>Skill profile</h3><span class="pill pill-blue"><?=count($skills)?> profiled</span></div><?php foreach($skills as $s):?><div class="verified-skill"><div><strong><?=h($s['skill_name'])?></strong><p><?=h($s['category_name']??'Skill')?> · Self-assessed: <?=h(level_label((int)$s['self_assessed_level']))?></p></div><?php if((int)$s['verified_level']>0):?><span class="pill pill-green">✓ <?=h(level_label((int)$s['verified_level']))?></span><?php else:?><span class="pill pill-amber">Not verified</span><?php endif;?></div><?php endforeach;?><?php if(!$skills):?><p class="muted small">Complete a career assessment to add skills to your profile.</p><?php endif;?></section><div class="stack"><section class="card card-pad"><div class="panel-title"><h3>Verified evidence</h3><a class="link-arrow" href="<?=h(url('evidence/index.php'))?>">Manage →</a></div><?php foreach($verified as $e):?><div class="verified-skill"><div><strong><?=h($e['title'])?></strong><p><?=h($e['skill_name'])?><?= $e['project_title']?' · '.h($e['project_title']):''?></p><?php if($e['evidence_url']):?><a class="link-arrow" target="_blank" rel="noopener noreferrer" href="<?=h($e['evidence_url'])?>">View evidence ↗</a><?php endif;?></div><span class="pill pill-green">Verified</span></div><?php endforeach;?><?php if(!$verified):?><p class="muted small">No evidence has been verified yet. Submit a project or practical work for review.</p><?php endif;?></section><section class="card card-pad"><div class="panel-title"><h3>Achievements</h3><span class="pill pill-blue"><?=count($achievements)?></span></div><?php foreach($achievements as $a):?><div class="activity-item"><div class="activity-dot">✦</div><div><strong><?=h($a['title'])?></strong><span><?=h($a['description'])?></span></div></div><?php endforeach;?><?php if(!$achievements):?><p class="muted small">Achievements appear as you complete assessments, submit evidence and finish roadmap milestones.</p><?php endif;?></section></div></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
